148	                                    let idx_zero = lv!(idx: 0);
149	                                    col_nc.eq(idx_zero, arena).node()
150	                                }
151	                            },
152	                            not_null: {
153	                                let col_min = col!(min: col);
154	                                let col_max = col!(max: col);
155	
156	                                let min_is_defined = is_stat_defined(col_min.node(), dtype, arena);
157	                                let max_is_defined = is_stat_defined(col_max.node(), dtype, arena);
158	
159	                                let min_gt = col_min.gt(lv_node, arena);
160	                                let min_gt = min_gt.and(min_is_defined, arena);
161	
162	                                let max_lt = col_max.lt(lv_node, arena);
163	                                let max_lt = max_lt.and(max_is_defined, arena);
164	
165	                                let col_nc = col!(null_count: col);
166	                                let len = col!(len);
167	                                let all_nulls = col_nc.eq(len, arena);
