16	fn get_binary_expr_col_and_lv<'a>(
17	    left: Node,
18	    right: Node,
19	    expr_arena: &'a Arena<AExpr>,
20	    schema: &Schema,
21	) -> Option<(
22	    (&'a PlSmallStr, Node),
