29	        constant_evaluate(right, expr_arena, schema, 0),
30	    ) {
31	        (Some(col), _, _, Some(lv)) => Some(((col, left), (lv, right))),
32	        (_, Some(col), Some(lv), _) => Some(((col, right), (lv, left))),
33	        _ => None,
34	    }
