/// Determine whether a constant literal is a floating-point `NaN`.
///
/// Returns `Some(true)` / `Some(false)` when the value is a known constant and `None` when the
/// literal is not known at plan time (and thus its NaN-ness cannot be determined).
fn literal_is_nan(lv: Option<&LiteralValue>) -> Option<bool> {
    let av = lv?.to_any_value()?;
    Some(match av {
        AnyValue::Float32(v) => v.is_nan(),
        AnyValue::Float64(v) => v.is_nan(),
        _ => false,
    })
}

/// Swap a comparison operator so that it reads with the column on the left-hand side.
///
/// e.g. `lit > col` becomes `col < lit`.
fn swap_comparison_operator(op: Operator) -> Operator {
    use Operator as O;
    match op {
        O::Lt => O::Gt,
        O::Gt => O::Lt,
        O::LtEq => O::GtEq,
        O::GtEq => O::LtEq,
        other => other,
    }
}

/// Whether a comparison between a float column and a literal can produce a *correct* skip-batch
/// predicate.
///
/// Parquet min/max statistics exclude `NaN`, so a batch may contain hidden `NaN` values that are
/// not reflected in the statistics. Under polars' total ordering `NaN` is the largest value, so:
///
